mapper.select:
select a.id as id, a.name as name, a.address_name as addressName, a.img_url as coverImg, cast(a.latitude as decimal(10, 7)) as lat, cast(a.longitude as decimal(10, 7)) as lng, a.start_date as startDate, a.end_date as endDate, a.create_time as createTime, a.club_id as clubId from cms_activity a where a.status = 1 and a.publish_status = 1 and coalesce(a.del_flag, 0) = 0 and a.cancel_time is null and (a.end_date is null or a.end_date > now()) and a.latitude is not null and a.latitude <> '' and a.longitude is not null and a.longitude <> '' and cast(a.latitude as decimal(10, 7)) between #{minLat} and #{maxLat} and cast(a.longitude as decimal(10, 7)) between #{minLng} and #{maxLng}
and (a.club_id is null or exists (select 1 from club_member cm where cm.club_id = a.club_id and cm.member_id = #{memberId} and cm.status = 1 and cm.del_flag = 0))
and a.club_id is null
order by a.start_date asc, a.id asc limit #{limit}
